import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, color, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, DoubleSide } = ctx.THREE;

  const COL = {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    border: '#26262f',
    gradTop: '#1a1a22',
    gradBot: '#111116',
  };

  const root = new Group();
  root.name = config?.id || 'testimonial-panel';

  const disposables = [];
  const timelines = [];

  // ---- Backdrop stage plane (engineered vertical gradient) ----
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  const bgTop = color(COL.gradTop);
  const bgBot = color(COL.gradBot);
  bgMat.colorNode = mix(bgBot, bgTop, uv().y);
  const bg = new Mesh(bgGeo, bgMat);
  bg.position.z = -2.5;
  root.add(bg);
  disposables.push(bgGeo, bgMat);

  // ---- Panel (3.4 x 1.9) with vertical albedo gradient + PBR ----
  const panelW = 3.4, panelH = 1.9;
  const panelGeo = new PlaneGeometry(panelW, panelH);
  const panelMat = new MeshStandardNodeMaterial();
  const pTop = color(COL.gradTop);
  const pBot = color(COL.gradBot);
  panelMat.colorNode = mix(pBot, pTop, uv().y);
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.side = DoubleSide;
  const panel = new Mesh(panelGeo, panelMat);
  panel.position.z = 0;
  root.add(panel);
  disposables.push(panelGeo, panelMat);

  // ---- Hairline border (slightly larger unlit frame behind panel) ----
  const borderGeo = new PlaneGeometry(panelW + 0.012, panelH + 0.012);
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = color(COL.border);
  const border = new Mesh(borderGeo, borderMat);
  border.position.z = -0.01;
  root.add(border);
  disposables.push(borderGeo, borderMat);

  // ---- Oversized quotation mark, extruded box-backed glyph ----
  const markGroup = new Group();
  markGroup.position.set(-panelW / 2 + 0.5, panelH / 2 - 0.5, 0.04);
  root.add(markGroup);

  // extruded backing slab for the mark so it reads as a machined element
  const markSlabGeo = new BoxGeometry(0.42, 0.42, 0.04);
  const markSlabMat = new MeshStandardNodeMaterial();
  markSlabMat.colorNode = color(COL.accent);
  markSlabMat.roughness = 0.5;
  markSlabMat.metalness = 0.3;
  const markSlab = new Mesh(markSlabGeo, markSlabMat);
  markSlab.position.set(0.1, -0.12, 0);
  markSlab.visible = false; // glyph carries the form; slab reserved
  markGroup.add(markSlab);
  disposables.push(markSlabGeo, markSlabMat);

  // ---- Text content bridge ----
  const items = config.textContent ?? config?.intent?.visualSpec?.textContent ?? [];
  const byRole = {};
  for (const it of items) {
    if (it && it.role && byRole[it.role] === undefined) byRole[it.role] = it.text;
  }

  const quoteMarkStr = byRole['quote-mark'] ?? '"';
  const quoteStr =
    byRole['quote'] ??
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.';
  const attributionStr = byRole['attribution'] ?? 'M. OKAFOR';
  const captionStr = byRole['caption'] ?? 'COLLECTOR SINCE 2019';

  const textMeshes = [];

  // oversized quote mark glyph
  const markText = ctx.fontAtlas.createText(quoteMarkStr, {
    fontSize: 120,
    color: COL.accent,
    align: 'left',
  });
  markGroup.add(markText);
  textMeshes.push(markText);

  // quote body
  const quoteText = ctx.fontAtlas.createText(quoteStr, {
    fontSize: 38,
    color: COL.paper,
    align: 'left',
    maxWidthPx: 480,
    letterSpacingPx: 0,
  });
  quoteText.position.set(-panelW / 2 + 0.5, panelH / 2 - 0.75, 0.03);
  root.add(quoteText);
  textMeshes.push(quoteText);

  // accent rule above attribution
  const ruleGeo = new PlaneGeometry(0.2, 0.02);
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.colorNode = color(COL.accent);
  ruleMat.emissiveNode = color(COL.accent).mul(1.4);
  ruleMat.roughness = 0.5;
  ruleMat.metalness = 0.2;
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(-panelW / 2 + 0.5 + 0.1, -panelH / 2 + 0.62, 0.03);
  root.add(rule);
  disposables.push(ruleGeo, ruleMat);

  // attribution
  const attribText = ctx.fontAtlas.createText(attributionStr, {
    fontSize: 26,
    color: COL.paper,
    align: 'left',
    letterSpacingPx: 2,
  });
  attribText.position.set(-panelW / 2 + 0.5, -panelH / 2 + 0.48, 0.03);
  root.add(attribText);
  textMeshes.push(attribText);

  // caption
  const captionText = ctx.fontAtlas.createText(captionStr, {
    fontSize: 18,
    color: '#9aa0ac',
    align: 'left',
    letterSpacingPx: 2,
  });
  captionText.position.set(-panelW / 2 + 0.5, -panelH / 2 + 0.3, 0.03);
  root.add(captionText);
  textMeshes.push(captionText);

  // ---- Node-local lighting: rim/accent + key raking light ----
  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(-2.5, 2.5, 3.0);
  root.add(key);

  const rim = new DirectionalLight(0xff2a38, 0.7);
  rim.position.set(3.0, -1.5, 2.0);
  root.add(rim);

  // ---- Apply cinematic primitives (spec ships none, but honor config) ----
  const primResults = [];
  const primList = config.cinematicPrimitives ?? [];
  for (const p of primList) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const res = fn(root, p.params || {});
      if (res) primResults.push(res);
    }
  }

  // ---- Mount animation: fade-up panel, weighted-settle mark ----
  panel.material.transparent = true;
  root.position.y += 0.2;

  const tl = gsap.timeline();
  tl.to(root.position, {
    y: root.position.y - 0.2,
    duration: 0.5,
    ease: 'power2.out',
  });
  markGroup.scale.setScalar(1.04);
  tl.to(
    markGroup.scale,
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0.1
  );
  timelines.push(tl);

  // ---- Cleanup ----
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primResults.forEach((r) => r.cleanup && r.cleanup());
    disposables.forEach((d) => d.dispose && d.dispose());
    textMeshes.forEach((m) => {
      m.traverse?.((o) => {
        o.geometry?.dispose?.();
        if (o.material) {
          (Array.isArray(o.material) ? o.material : [o.material]).forEach((mm) =>
            mm.dispose?.()
          );
        }
      });
    });
  };

  return root;
}
